ci = p5_defn.entities.add_instance(child, Geom::Transformation.new)
ci.name = "Step 5.4 — Spray bar (over the processing tray)"
ci.layer = model.layers["P5 Spray Bar"]
ci.set_attribute("dynamic_attributes", "_name", "P5Step5_4")
ci.set_attribute("dynamic_attributes", "hidden", 1.0)
ci.set_attribute("dynamic_attributes", "_hidden_formula", "Phase5Build!step<4")
p5_inst = entities.add_instance(p5_defn, Geom::Transformation.new)
p5_inst.name = "Phase 5 Build"
p5_inst.set_attribute("dynamic_attributes", "_name", "Phase5Build")
p5_inst.set_attribute("dynamic_attributes", "step", 1.0)
p5_inst.set_attribute("dynamic_attributes", "_step_access", "VIEW")
p5_inst.set_attribute("dynamic_attributes", "_step_label", "Build step")
p5_inst.set_attribute("dynamic_attributes", "onclick", 'ANIMATE("step",1,2,3,4)')
p5_inst.set_attribute("dynamic_attributes", "_onclick_access", "NONE")

# ── Drop the external evap cooler UNIT + its cord (ov.electrical() draws them) — not part of
#    the container construction. The panel provisions (Fuse E, Cct-E GFCI outlet) stay.
model.definitions.each { |d| d.entities.grep(Sketchup::Group).each { |g| g.erase! if g.valid? && g.name =~ /Evap Cooler|cooler cord/ } }

# ── In-model © + license credit (default layer → shown in every scene) ──
lbb = model.bounds
lanc = Geom::Point3d.new(lbb.min.x, lbb.min.y - 400.mm, lbb.min.z)
entities.add_text("© 2026 Alvin Richards
Licensed under GNU AGPLv3
alvinr.github.io/tbs", lanc)
model.definitions.purge_unused
model.materials.purge_unused

# ── Remove stale tags from earlier versions ──
keep_tags = ["Context", "P1 IBC Frame", "P1 Near IBCs", "P1 IBC Plumbing", "P1 Fan A", "P1 Far IBCs", "P1 Hinge Panel", "P3 Wall Backing", "P3 Far+Right Cantilevers", "P3 Near Cantilevers", "P3 Ribbons + Filter Skid", "P3 Pinhole Plumbing", "P3 Processing Tray", "P3 Film-Plane Beams", "P3 Left Cantilevers", "P3 Walkway", "P4 External Panel", "P4 Electrical Panel", "P4 Corridor Wiring", "P4 Lights", "P4 Wiring + Fit-out", "P5 Pinhole", "P5 Film Plane", "P5 Light Trap", "P5 Spray Bar", "P1-static", "P3-static", "P4-static", "P5-static"]
default_layer = model.layers[0]
model.layers.to_a.each { |l|
  next if l == default_layer || keep_tags.include?(l.name)
  model.layers.remove(l, true) rescue nil
}

# ── Camera: one shared iso, framed on the whole container ──
model.layers.each { |l| l.visible = true }
bb = model.bounds
ctr = bb.center
dir = Geom::Vector3d.new(0.72, -0.7, 0.5); dir.normalize!
eye = ctr.offset(dir, bb.diagonal * 1.5)
model.active_view.camera = Sketchup::Camera.new(eye, ctr, Z_AXIS)
model.active_view.zoom_extents

# ── Cumulative phase scenes ──
[["Phase 1 — Geometry Set-Out", ["Context", "P1 IBC Frame", "P1 Near IBCs", "P1 IBC Plumbing", "P1 Fan A", "P1 Far IBCs", "P1 Hinge Panel"]], ["Phase 3 — Framing", ["Context", "P1-static", "P3 Wall Backing", "P3 Far+Right Cantilevers", "P3 Near Cantilevers", "P3 Ribbons + Filter Skid", "P3 Pinhole Plumbing", "P3 Processing Tray", "P3 Film-Plane Beams", "P3 Left Cantilevers", "P3 Walkway"]], ["Phase 4 — Electrical", ["Context", "P1-static", "P3-static", "P4 External Panel", "P4 Electrical Panel", "P4 Corridor Wiring", "P4 Lights", "P4 Wiring + Fit-out"]], ["Phase 5 — Photo System", ["Context", "P1-static", "P3-static", "P4-static", "P5 Pinhole", "P5 Film Plane", "P5 Light Trap", "P5 Spray Bar"]]].each { |name, tags|
  model.layers.each { |l| l.visible = (l == default_layer || tags.include?(l.name)) }
  page = model.pages.add(name)
  page.use_camera = true
}
model.layers.each { |l| l.visible = true }

model.commit_operation

# Register the phase click-to-build DCs with the Dynamic Components engine so the Interact tool
# drives them (skipped silently if the DC extension isn't loaded).
if defined?($dc_observers) && $dc_observers.respond_to?(:get_latest_class)
  cls = $dc_observers.get_latest_class
  if cls
    cls.redraw_with_undo(p1_inst) rescue nil
    cls.redraw_with_undo(p3_inst) rescue nil
    cls.redraw_with_undo(p4_inst) rescue nil
    cls.redraw_with_undo(p5_inst) rescue nil
  end
end

# Re-assert the fully-built default (the ANIMATE redraw above resets the first DC's step).
p1_inst.set_attribute("dynamic_attributes", "step", 1.0)
p1_inst.definition.entities.grep(Sketchup::ComponentInstance).each_with_index { |c, i| c.set_attribute("dynamic_attributes", "hidden", i == 0 ? 0.0 : 1.0); c.visible = (i == 0) }
p3_inst.set_attribute("dynamic_attributes", "step", 1.0)
p3_inst.definition.entities.grep(Sketchup::ComponentInstance).each_with_index { |c, i| c.set_attribute("dynamic_attributes", "hidden", i == 0 ? 0.0 : 1.0); c.visible = (i == 0) }
p4_inst.set_attribute("dynamic_attributes", "step", 1.0)
p4_inst.definition.entities.grep(Sketchup::ComponentInstance).each_with_index { |c, i| c.set_attribute("dynamic_attributes", "hidden", i == 0 ? 0.0 : 1.0); c.visible = (i == 0) }
p5_inst.set_attribute("dynamic_attributes", "step", 1.0)
p5_inst.definition.entities.grep(Sketchup::ComponentInstance).each_with_index { |c, i| c.set_attribute("dynamic_attributes", "hidden", i == 0 ? 0.0 : 1.0); c.visible = (i == 0) }

{ success: true, model: "Construction Sequence",
   components: model.entities.grep(Sketchup::ComponentInstance).length,
   tags: model.layers.count, scenes: model.pages.count }.to_json
